$m3_l14_t10_starter$, $m3_l14_t10_solution$import sqlite3
def transfer(path, from_id, to_id, amount):
    con=sqlite3.connect(path)
    try:
        balance=con.execute("SELECT balance FROM accounts WHERE id=?", (from_id,)).fetchone()[0]
        if balance < amount: raise ValueError("not enough money")
        con.execute("UPDATE accounts SET balance=balance-? WHERE id=?", (amount,from_id))
        con.execute("UPDATE accounts SET balance=balance+? WHERE id=?", (amount,to_id))
        con.commit()
    except Exception:
        con.rollback(); raise
    finally:
        con.close()
