    $m3_l25_ttitle_4$Почини$m3_l25_ttitle_4$,
    $m3_l25_ttitle_6$Контроль$m3_l25_ttitle_6$
  )
)
DELETE FROM task_test_cases tc
USING target_tasks tt
WHERE tc.task_id = tt.id;

