,'success'),(5,5,11200,'success');\n","tests":[{"expected_rows":[["electronics",64100],["bags",12600],["stationery",14000]],"visibility":"public"}],"compare":{"mode":"rows_exact","order_matters":true}},"hints":[],"hints_visibility":"button_or_after_failed_attempts","ai_hint_config":{"mode":"socratic","no_full_solution":true},"ai_review_config":null,"admin_notes":"SQL. Seed and solution hidden."}$m3_l29_t25_policy$::jsonb),
