  WHERE c.slug = 'python-zero' AND m.position = 4 AND l.position = 1
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

