  WHERE c.slug = 'python-zero' AND m.position = 4 AND l.position = 20
), target_tasks AS (
  SELECT t.id
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
  WHERE t.title IN (
