    $m4_l26_ttitle_4$Почини$m4_l26_ttitle_4$,
    $m4_l26_ttitle_6$Контроль$m4_l26_ttitle_6$
  )
)
DELETE FROM task_test_cases tc
USING target_tasks tt
WHERE tc.task_id = tt.id;

