INSERT INTO tasks(lesson_id, title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy, is_published)
SELECT lr.lesson_id, ts.title, ts.statement_md, ts.starter_code, ts.solution_code, ts.difficulty, ts.xp_reward, ts.topic, ts.language, ts.source_policy, TRUE
FROM lesson_ref lr
CROSS JOIN task_seed ts
ON CONFLICT (lesson_id, title) DO UPDATE
SET statement_md = EXCLUDED.statement_md,
    starter_code = EXCLUDED.starter_code,
    solution_code = EXCLUDED.solution_code,
    difficulty = EXCLUDED.difficulty,
    xp_reward = EXCLUDED.xp_reward,
    topic = EXCLUDED.topic,
    language = EXCLUDED.language,
    source_policy = EXCLUDED.source_policy,
    is_published = TRUE,
    updated_at = NOW();

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id
  WHERE c.slug = 'python-zero' AND m.position = 5 AND l.position = 25
), target_tasks AS (
  SELECT t.id
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
  WHERE t.title IN (
    $m5_l25_ttitle_2$ТЗ$m5_l25_ttitle_2$,
    $m5_l25_ttitle_3$Схема БД$m5_l25_ttitle_3$,
    $m5_l25_ttitle_4$API contract$m5_l25_ttitle_4$,
    $m5_l25_ttitle_5$Core API$m5_l25_ttitle_5$,
    $m5_l25_ttitle_6$Auth$m5_l25_ttitle_6$,
    $m5_l25_ttitle_7$AI feature$m5_l25_ttitle_7$,
    $m5_l25_ttitle_8$Docker CI$m5_l25_ttitle_8$,
    $m5_l25_ttitle_9$Deploy docs$m5_l25_ttitle_9$,
    $m5_l25_ttitle_10$Load review$m5_l25_ttitle_10$,
    $m5_l25_ttitle_11$Defense$m5_l25_ttitle_11$,
    $m5_l25_ttitle_12$Observability$m5_l25_ttitle_12$,
    $m5_l25_ttitle_13$Rate limit$m5_l25_ttitle_13$,
    $m5_l25_ttitle_14$Data backup$m5_l25_ttitle_14$,
    $m5_l25_ttitle_15$Security review$m5_l25_ttitle_15$,
    $m5_l25_ttitle_16$Performance note$m5_l25_ttitle_16$,
    $m5_l25_ttitle_17$API contract (шаг 17)$m5_l25_ttitle_17$,
    $m5_l25_ttitle_18$DB transaction$m5_l25_ttitle_18$,
    $m5_l25_ttitle_19$Auth security$m5_l25_ttitle_19$,
    $m5_l25_ttitle_20$AI mock tests$m5_l25_ttitle_20$,
    $m5_l25_ttitle_21$RAG eval$m5_l25_ttitle_21$,
    $m5_l25_ttitle_22$Observability (шаг 22)$m5_l25_ttitle_22$,
    $m5_l25_ttitle_23$Deploy checklist$m5_l25_ttitle_23$,
    $m5_l25_ttitle_24$Defense (шаг 24)$m5_l25_ttitle_24$,
    $m5_l25_ttitle_26$Production checklist$m5_l25_ttitle_26$
  )
)
DELETE FROM task_test_cases tc
USING target_tasks tt
WHERE tc.task_id = tt.id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id
  WHERE c.slug = 'python-zero' AND m.position = 5 AND l.position = 25
), task_lookup AS (
  SELECT t.title, t.id AS task_id
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
